css:
@font-face {
    font-family: 'Libre Barcode 128';
    font-style: normal;
    font-weight: 400;
    src: url(data:font/truetype;charset=utf-8;base64,) format('truetype');
}
@page { size: 58mm auto; margin: 0; }
body, .print-format { width: 58mm; margin: 0 auto; padding: 2mm; }
body, .print-format, .print-format * {
    font-family: 'Courier New', monospace !important;
    font-size: 10px !important;
    line-height: 1.05 !important;
    color: #000 !important;
}
.center { text-align: center; }
.right  { text-align: right; }
.bold   { font-weight: bold; }
.hr     { border-top: 1px dashed #000; margin: 0.5mm 0; height: 0; }
.dhr    { border-top: 2px solid #000; margin: 0.5mm 0; height: 0; }
table { width: 100%; border-collapse: collapse; }
td, th { padding: 0; vertical-align: top; }
.logo { max-width: 35mm; height: auto; margin: 0 auto 1mm; display: block; }
.brand { font-size: 13px !important; font-weight: bold; letter-spacing: 0.5px; }
.muted { color: #444 !important; }
.barcode { margin: 1mm 0 0.5mm; text-align: center; }
.barcode-line {
    font-family: 'Libre Barcode 128' !important;
    font-size: 38px !important;
    line-height: 1 !important;
    letter-spacing: 0 !important;
    color: #000 !important;
}
.terms { font-size: 9px !important; }
.terms ul { padding-left: 4mm; margin: 0.5mm 0; }
.terms li { margin: 0; padding: 0; }
.promo { font-size: 9px !important; font-weight: bold; text-align: center; }
.addr { font-size: 9px !important; }

html:
{# SUNGAS_COMPLIANCE_PATCH_v2 #}
{# SUNGAS_COMPLIANCE_PATCH_v3 #}
{# SUNGAS_0039 cylinder sizes + ORIGINAL/DUPLICATE + filler slip #}
{%- set copy = receipt_copy(doc) -%}

{%- set OUTLET_DIRECTORY = {
    "ikeja":           ("9 (old no 1) Obasa Road, Off Oba Akran Avenue, Ikeja, Lagos.", "08077683893, 08108815444, 09055493507, 09055493508"),
    "pedro":           ("38/40 Salami Shuaibu Street, Pedro, Somolu, Lagos.", "08077677436, 09055493507, 09055493508"),
    "bolade":          ("11 Oyetayo Street, Mafoluku, Oshodi, Lagos.", "08077683893, 08108815444, 09055493507, 09055493508"),
    "aseese":          ("Km 32, Lagos-Ibadan Expressway, Aseese Bus-Stop, Ogun State.", "08108815444, 09055493507, 09055493508"),
    "ijuotta":         ("Kilometre 14, Idiroko Road, Iju Town, Custom Bus-Stop, Ogun State.", "08108815444, 09055493507, 09055493508"),
    "osiotta":         ("Ikola Road, 10-10 Bus-Stop, Osi-Ota, Ogun State.", "08108815444, 09055493507, 09055493508"),
    "sefu":            ("Along Sefu Elede Road, Bale Palace Bus-Stop, Ibafo, Ogun State.", "08108815444, 09055493507, 09055493508"),
    "maba":            ("Asese-Maba Town Road off Lagos-Ibadan Expressway, Asese Bus-Stop, Ogun State.", "08108815444, 07059619769, 09055493507, 09055493508"),
    "ijoko":           ("Ijoko-Agbado Road, Abule Bus-Stop, Ijoko-Lemode, Ogun State.", "08077683893, 08108815444, 09055493507, 09055493508"),
    "ebutte":          ("91 Ebute Road, Opp. Gideon Comprehensive High School, Ibafo, Ogun State.", "09049474274, 08108815444, 09055493507, 09055493508"),
    "uppermission":    ("159 Upper Mission Road, Benin City, Edo State.", "08077683770, 09055493507, 09055493508"),
    "idokpa":          ("285 Benin-Auchi Road, Idokpa Qtrs, Benin City, Edo State.", "08108815444, 07059619773, 09055493507, 09055493508"),
    "ekehuan":         ("Opp. Ogede Secondary School, Ekehuan Road, Benin City, Edo State.", "08077683810, 09055493507, 09055493508"),
    "okhuoromi":       ("Along Ebo-Sapele Road, Okhuoromi, Benin City, Edo State.", "08108815444, 09037950596, 09055493507, 09055493508"),
    "idowina":         ("By Underground Church, off Upper Mission Extension, Idowina, Benin City, Edo State.", "08108815444, 07059619773, 09055493507, 09055493508"),
    "asaba":           ("Marine Road, Behind Total Filling Station, Cable Point, Nnebisi Road, Asaba.", "08077683893, 08108815444, 09055493507, 09055493508"),
    "reclamation":     ("7 Reclamation Rd, Macoba, Old Port Harcourt Twp, Port Harcourt.", "09028696786, 09055493507, 09055493508"),
    "eleme":           ("Km 15, PH-Eleme-Bori Road, Eleme, Rivers State.", "08059044977, 09055493507, 09055493508"),
    "itele":           ("52B Adeleye Street, by Shogbade Filling Station, Lafenwa Road, Ayetoro-Itele, Ogun State.", "09022186682, 09055493507, 09055493508"),
    "bulksalesbenin":  ("159 Upper Mission Road, Benin City, Edo State.", "08077683770, 07066691434, 09055493507, 09055493508"),
    "mafoluku":        ("161 Oshodi Road, Mafoluku, Oshodi, Lagos.", "08077683893, 08108815444, 09055493507, 09055493508"),
    "oworo":           ("2 Adeniji Street, Oworonshoki, Kosofe, Lagos.", "08077683893, 08108815444, 09055493507, 09055493508")
} -%}
{%- set company = frappe.get_doc("Company", doc.company) %}
{# SUNGAS_COMPLIANCE_PATCH_v1 -- per-outlet legal entity branding #}
{%- set pos_profile_doc = frappe.get_doc("POS Profile", doc.pos_profile) if doc.pos_profile else None %}
{%- set legal_entity_name = (pos_profile_doc.custom_legal_entity_name if pos_profile_doc else None) or company.company_name or "SUNGAS COMPANY LIMITED" %}
{%- set legal_entity_tin = pos_profile_doc.custom_legal_entity_tin if pos_profile_doc else "" %}
{%- set legal_entity_address = pos_profile_doc.custom_legal_entity_address if pos_profile_doc else "" %}

{%- set logo_url = company.company_logo or "/files/sungas-logo.png" %}
{%- set outlet_label_raw = doc.pos_profile.replace("POS - ", "").replace(" (Test)", "") if doc.pos_profile else "" %}
{%- set outlet_key = (outlet_label_raw or "")|lower %}
{%- set outlet_key = outlet_key.replace(" ", "").replace("-", "").replace(".", "") %}
{%- set outlet_info = OUTLET_DIRECTORY.get(outlet_key) %}
{%- set plant_address = outlet_info[0] if outlet_info else "Sungas Company Limited, Nigeria." %}
{%- set contact_phone = outlet_info[1] if outlet_info else "09055493507, 09055493508" %}
{%- set total_qty = (doc.items|sum(attribute="qty"))|round(2) %}
{%- set lpg_total_kg = lpg_kg(doc) %}
{%- set barcode_payload = doc.name ~ "|" ~ ((lpg_total_kg ~ "") if lpg_total_kg else total_qty) %}
{%- set lines = receipt_lines(doc) %}
{%- set fills = lines|selectattr("fill")|list %}
{%- set fill_by = frappe.utils.formatdate(doc.get("sungas_fill_due") or frappe.utils.add_days(doc.posting_date, 7), "dd-MM-yyyy") %}

<div class="print-format">
{%- if copy.blocked %}
<div class="center bold" style="font-size: 13px !important; border: 1px solid #000; padding: 1mm;">{{ copy.label }}</div>
<div class="center" style="margin-top: 2mm;">Receipt {{ doc.name }} has already been printed.<br/>Only a Plant Manager can print a duplicate.<br/>This attempt by {{ copy.by }} at {{ copy.at }} has been recorded.</div>
{%- else %}

<div class="center">
    <div class="brand">{{ (legal_entity_name or "SUNGAS COMPANY LIMITED")|upper }}</div>
    <div class="bold" style="font-size: 11px !important; margin-top: 0.5mm;">RECEIPT</div>
    <div class="bold" style="font-size: 11px !important; border: 1px solid #000; margin: 0.5mm 6mm; padding: 0.3mm;">{{ copy.label }}</div>
    {% if legal_entity_tin %}<div class="muted" style="font-size: 9px !important;">TIN: {{ legal_entity_tin }}</div>{% endif %}
    {% if legal_entity_address %}<div class="muted" style="font-size: 9px !important;">{{ legal_entity_address }}</div>{% endif %}
</div>
<div class="dhr"></div>

<table>
    <tr><td>Receipt No:</td><td class="right">{{ doc.name }}</td></tr>
    <tr><td>Cashier:</td><td class="right">{{ doc.owner }}</td></tr>
    <tr><td>Customer:</td><td class="right">{{ doc.customer_name or doc.customer }}</td></tr>
    <tr><td>Date:</td><td class="right">{{ frappe.utils.format_datetime(doc.posting_date, "dd-MM-yyyy") }}</td></tr>
    <tr><td>Time:</td><td class="right">{{ (doc.posting_time|string)[:8] if doc.posting_time else "" }}</td></tr>
    {% if outlet_label_raw %}<tr><td>Outlet:</td><td class="right">{{ outlet_label_raw }}</td></tr>{% endif %}
</table>
<div class="hr"></div>

<table>
    <thead><tr class="bold"><td>Item</td><td class="right" style="width: 11mm;">Qty</td><td class="right" style="width: 19mm;">Amount</td></tr></thead>
    <tbody>
    {% for it in doc.items %}
        {%- set ln = lines[loop.index0] %}
        <tr>
            <td>{{ it.item_name or it.item_code }}{% if ln.cyl %} - {{ it.uom }}{% endif %}</td>
            <td class="right">{{ "%g"|format(it.qty) if ln.cyl else "%.2f"|format(it.qty) }}</td>
            <td class="right">{{ frappe.format_value(it.amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td>
        </tr>
        <tr><td colspan="3" class="muted">&nbsp;&nbsp;@ {{ frappe.format_value(it.rate, {"fieldtype": "Currency", "options": doc.currency}) }}{% if it.uom %} / {{ it.uom }}{% endif %}{% if ln.cyl and ln.kg %} ({{ "%g"|format(ln.kg) }} kg){% endif %}</td></tr>
        {%- if ln.kg is not none and not ln.cyl %}<tr><td colspan="3" class="muted">&nbsp;&nbsp;Fill into: {{ ln.fill_into or "Customer's own / unknown" }}</td></tr>{% endif %}
    {% endfor %}
    {%- if lpg_total_kg %}<tr class="bold"><td colspan="2">Total LPG</td><td class="right">{{ "%g"|format(lpg_total_kg) }} kg</td></tr>{% endif %}
    </tbody>
</table>
<div class="hr"></div>

<table>
    <tr><td>Subtotal (Net of VAT)</td><td class="right">{{ frappe.format_value(doc.net_total, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
    <tr><td>VAT @ 0%</td><td class="right">{{ frappe.format_value(doc.total_taxes_and_charges or 0, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
    {% if doc.discount_amount %}<tr><td>Discount</td><td class="right">- {{ frappe.format_value(doc.discount_amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>{% endif %}
    <tr><td class="bold">Grand Total</td><td class="right bold">{{ frappe.format_value(doc.grand_total, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
    {% if (doc.rounding_adjustment or 0)|float|abs > 0.01 %}<tr><td>Cash rounding (no change)</td><td class="right">{{ frappe.format_value(doc.rounding_adjustment, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>{% endif %}
    <tr><td class="bold">Rounded Total</td><td class="right bold">{{ frappe.format_value(doc.rounded_total or doc.grand_total, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
</table>
<div class="hr"></div>

<table>
    {% for p in doc.payments %}<tr><td>{{ p.mode_of_payment }}</td><td class="right">{{ frappe.format_value(p.amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>{% endfor %}
    <tr class="bold"><td>Paid Amount</td><td class="right">{{ frappe.format_value(doc.paid_amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
    {% if (doc.change_amount or 0)|float|abs > 0.01 %}<tr><td>Change</td><td class="right">{{ frappe.format_value(doc.change_amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>{% endif %}
</table>
<div class="hr"></div>

<div class="barcode">
    <div class="barcode-line">*{{ barcode_payload }}*</div>
    <div class="muted">{{ barcode_payload }}</div>
</div>
<div class="hr"></div>

<div class="terms">
    <div class="bold">Terms &amp; Conditions:</div>
    <ul>
        <li>Goods sold are not returnable.</li>
        <li>Check cylinders before leaving the plant.</li>
        {%- if lpg_total_kg %}<li>Gas must be filled by {{ fill_by }}. After that, see the Plant Manager.</li>{% endif %}
    </ul>
</div>
<div class="hr"></div>

<div class="addr muted">
    Plant Address: {{ plant_address }}<br/>
    Contact No: {{ contact_phone }}
</div>
<div class="hr"></div>

<div class="promo">GAS DELIVERY NOW AVAILABLE IN PARTNERSHIP WITH VERVEFLAME -- 09055493507, 09055493508.</div>
<div class="hr"></div>

<div class="center bold">Thank you, please visit again.</div>

{%- if fills and not copy.email %}
<div style="page-break-before: always;"></div>
<div class="center brand">FILLER SLIP</div>
<div class="center bold" style="border: 1px solid #000; margin: 0.5mm 6mm; padding: 0.3mm;">{{ copy.label }}</div>
<table>
    <tr><td>Receipt No:</td><td class="right">{{ doc.name }}</td></tr>
    <tr><td>Time:</td><td class="right">{{ frappe.utils.format_datetime(doc.posting_date, "dd-MM-yyyy") }} {{ (doc.posting_time|string)[:5] if doc.posting_time else "" }}</td></tr>
    {% if outlet_label_raw %}<tr><td>Outlet:</td><td class="right">{{ outlet_label_raw }}</td></tr>{% endif %}
    <tr><td>Customer:</td><td class="right">{{ doc.customer_name or doc.customer }}</td></tr>
    <tr><td>Fill by:</td><td class="right bold">{{ fill_by }}</td></tr>
</table>
<div class="hr"></div>
{%- for l in fills %}<div class="bold" style="font-size: 12px !important;">[ ] {{ l.fill }}</div>{% endfor %}
<div class="hr"></div>
<div>Total to fill: <b>{{ "%g"|format(lpg_total_kg) }} kg</b></div>
<div class="barcode">
    <div class="barcode-line">*{{ barcode_payload }}*</div>
    <div class="muted">{{ barcode_payload }}</div>
</div>
<div style="margin-top: 3mm;">Filled by: ____________________</div>
<div style="margin-top: 3mm;">Checked by: __________________</div>
{%- endif %}
{%- endif %}

</div>

{% set company_doc = frappe.get_cached_doc("Company", doc.company) %}
{% set emp = frappe.get_cached_doc("Employee", doc.employee) %}
{% set period_label = frappe.utils.formatdate(doc.start_date, "MMMM yyyy") %}

<style>
  .sungas-slip { font-family: "Helvetica", "Arial", sans-serif; color:#1f2937;
                 font-size:8.5pt; line-height:1.2; max-width:380px; margin:0 auto; }
  .sungas-slip h1 { font-size:11pt; margin:0; color:#0f3a52; letter-spacing:0.3px; }
  .sungas-slip h2 { font-size:8pt; margin:0 0 2px 0; color:#0f3a52;
                    text-transform:uppercase; letter-spacing:0.4px;
                    border-bottom:1px solid #0f3a52; padding-bottom:1px; }
  .sungas-slip .hdr { border-bottom:1.5px solid #0f3a52; padding-bottom:4px; margin-bottom:6px;
                      text-align:center; }
  .sungas-slip .hdr-sub { font-size:7.5pt; color:#64748b; margin-top:1px; }
  .sungas-slip .hdr-meta { font-size:7pt; color:#475569; margin-top:2px; }
  .sungas-slip .info-grid { display:grid; grid-template-columns:1fr 1fr; gap:0 10px;
                            margin-bottom:6px; font-size:7.5pt; }
  .sungas-slip .info-grid .cell { display:grid; grid-template-columns:54px 1fr; padding:0; }
  .sungas-slip .info-grid .lbl { color:#64748b; }
  .sungas-slip .info-grid .val { font-weight:600; }
  .sungas-slip table.tbl { width:100%; border-collapse:collapse; margin:0;
                           font-size:8pt; }
  .sungas-slip table.tbl td { padding:1.5px 4px; vertical-align:top; }
  .sungas-slip table.tbl td.amt { text-align:right; font-variant-numeric:tabular-nums; }
  .sungas-slip table.tbl tr.tbl-row td { border-bottom:1px dashed #e2e8f0; }
  .sungas-slip table.tbl tr.tbl-total td { border-top:1px solid #0f3a52;
                                            padding-top:3px; font-weight:700; }
  .sungas-slip .ed-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px;
                          margin-bottom:6px; }
  .sungas-slip .net-box { background:#f0f7fc; border:1px solid #0f3a52;
                          padding:5px 8px; margin:6px 0 3px 0;
                          display:flex; justify-content:space-between; align-items:center; }
  .sungas-slip .net-box .lbl { font-size:8pt; color:#0f3a52; font-weight:600;
                                text-transform:uppercase; letter-spacing:0.4px; }
  .sungas-slip .net-box .val { font-size:11pt; font-weight:700; color:#0f3a52;
                                font-variant-numeric:tabular-nums; }
  .sungas-slip .words { font-style:italic; color:#475569; margin:0 0 5px 0; font-size:7.5pt; }
  .sungas-slip .stat-block { background:#fafafa; border:1px solid #e2e8f0;
                              padding:3px 6px; margin-bottom:5px; font-size:7.5pt;
                              color:#475569; }
  .sungas-slip .stat-block h2 { font-size:7.5pt; border:none; padding:0; margin-bottom:2px; color:#64748b; }
  .sungas-slip .stat-block table { width:100%; }
  .sungas-slip .stat-block td { padding:1px 3px; }
  .sungas-slip .stat-block td.amt { text-align:right; font-variant-numeric:tabular-nums; }
  .sungas-slip .pay-details { font-size:7.5pt; display:grid; grid-template-columns:auto 1fr;
                              gap:0 10px; margin-bottom:5px; }
  .sungas-slip .pay-details .lbl { color:#64748b; }
  .sungas-slip .pay-details .val { font-weight:600; font-family:monospace; }
  .sungas-slip .footer { font-size:6.5pt; color:#94a3b8; text-align:center;
                          margin-top:4px; border-top:1px solid #e2e8f0; padding-top:3px;
                          line-height:1.3; }
</style>

<div class="sungas-slip">

  <!-- HEADER -->
  <div class="hdr">
    <h1>{{ doc.company }}</h1>
    <div class="hdr-sub">Payslip for {{ period_label }}</div>
    <div class="hdr-meta">
      Slip #{{ doc.name }} &nbsp;|&nbsp;
      Pay Date: {{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}
    </div>
  </div>

  <!-- EMPLOYEE + PERIOD: single block, 2-col data grid -->
  <h2>Employee &amp; Pay Period</h2>
  <div class="info-grid">
    <div class="cell"><span class="lbl">Name</span>    <span class="val">{{ doc.employee_name }}</span></div>
    <div class="cell"><span class="lbl">Staff ID</span><span class="val">{{ doc.employee }}</span></div>
    <div class="cell"><span class="lbl">Dept</span>    <span class="val">{{ doc.department or "—" }}</span></div>
    <div class="cell"><span class="lbl">Role</span>    <span class="val">{{ doc.designation or "—" }}</span></div>
    <div class="cell"><span class="lbl">Branch</span>  <span class="val">{{ doc.branch or "—" }}</span></div>
    {% if emp.grade_level %}
    <div class="cell"><span class="lbl">Grade</span>   <span class="val">{{ emp.grade_level }}</span></div>
    {% endif %}
    <div class="cell"><span class="lbl">Start</span>   <span class="val">{{ frappe.utils.formatdate(doc.start_date, "dd MMM yyyy") }}</span></div>
    <div class="cell"><span class="lbl">End</span>     <span class="val">{{ frappe.utils.formatdate(doc.end_date, "dd MMM yyyy") }}</span></div>
  </div>

  <!-- EARNINGS + DEDUCTIONS side-by-side -->
  <div class="ed-grid">
    <div>
      <h2>Earnings</h2>
      <table class="tbl">
        {% set ns_earn = namespace(rows=0) %}
        {% for e in doc.earnings %}
          {% if not e.statistical_component and not e.do_not_include_in_total and (e.amount or 0) > 0 %}
            {% set ns_earn.rows = ns_earn.rows + 1 %}
            <tr class="tbl-row">
              <td>{{ e.salary_component }}</td>
              <td class="amt">{{ "{:,.2f}".format(e.amount or 0) }}</td>
            </tr>
          {% endif %}
        {% endfor %}
        {% if ns_earn.rows == 0 %}
          <tr class="tbl-row"><td colspan="2" style="color:#94a3b8;font-style:italic;">No earnings.</td></tr>
        {% endif %}
        <tr class="tbl-total">
          <td>Gross Pay</td>
          <td class="amt">{{ "{:,.2f}".format(doc.gross_pay or 0) }}</td>
        </tr>
      </table>
    </div>

    <div>
      <h2>Deductions</h2>
      <table class="tbl">
        {% set ns_ded = namespace(rows=0) %}
        {% for d in doc.deductions %}
          {% if not d.statistical_component and not d.do_not_include_in_total and (d.amount or 0) > 0 %}
            {% set ns_ded.rows = ns_ded.rows + 1 %}
            <tr class="tbl-row">
              <td>{{ d.salary_component }}</td>
              <td class="amt">{{ "{:,.2f}".format(d.amount or 0) }}</td>
            </tr>
          {% endif %}
        {% endfor %}
        {% if doc.total_loan_repayment and doc.total_loan_repayment > 0 %}
          <tr class="tbl-row">
            <td>Total Loan</td>
            <td class="amt">{{ "{:,.2f}".format(doc.total_loan_repayment) }}</td>
          </tr>
          {% set ns_ded.rows = ns_ded.rows + 1 %}
        {% endif %}
        {% if ns_ded.rows == 0 %}
          <tr class="tbl-row"><td colspan="2" style="color:#94a3b8;font-style:italic;">No deductions.</td></tr>
        {% endif %}
        <tr class="tbl-total">
          <td>Total Deduction</td>
          <td class="amt">{{ "{:,.2f}".format((doc.total_deduction or 0) + (doc.total_loan_repayment or 0)) }}</td>
        </tr>
      </table>
    </div>
  </div>

  <!-- NET PAY -->
  <div class="net-box">
    <span class="lbl">Net Pay</span>
    <span class="val">NGN {{ "{:,.2f}".format(doc.net_pay or 0) }}</span>
  </div>
  {% if doc.total_in_words %}
    <div class="words"><em>{{ doc.total_in_words }}</em></div>
  {% endif %}

  <!-- EMPLOYER CONTRIBUTIONS (statistical / company-paid) -->
  {% set has_stat = [] %}
  {% for e in doc.earnings %}{% if e.statistical_component and (e.amount or 0) > 0 %}{% set _ = has_stat.append(1) %}{% endif %}{% endfor %}
  {% for d in doc.deductions %}{% if d.statistical_component and (d.amount or 0) > 0 %}{% set _ = has_stat.append(1) %}{% endif %}{% endfor %}
  {% if has_stat %}
  <div class="stat-block">
    <h2>Employer Contributions (not deducted from Net)</h2>
    <table>
      {% for e in doc.earnings %}
        {% if e.statistical_component and (e.amount or 0) > 0 %}
        <tr>
          <td>{{ e.salary_component }}</td>
          <td class="amt">{{ "{:,.2f}".format(e.amount or 0) }}</td>
        </tr>
        {% endif %}
      {% endfor %}
      {% for d in doc.deductions %}
        {% if d.statistical_component and (d.amount or 0) > 0 %}
        <tr>
          <td>{{ d.salary_component }}</td>
          <td class="amt">{{ "{:,.2f}".format(d.amount or 0) }}</td>
        </tr>
        {% endif %}
      {% endfor %}
    </table>
  </div>
  {% endif %}

  <!-- PAYMENT DETAILS -->
  {% if doc.bank_name or doc.bank_account_no %}
  <div class="pay-details">
    {% if doc.bank_name %}
      <span class="lbl">Bank:</span><span class="val" style="font-family:inherit;">{{ doc.bank_name }}</span>
    {% endif %}
    {% if doc.bank_account_no %}
      {% set acct = doc.bank_account_no | string %}
      {% set masked = "•••••• " + acct[-4:] if acct|length >= 4 else acct %}
      <span class="lbl">Account:</span><span class="val">{{ masked }}</span>
    {% endif %}
    {% if doc.mode_of_payment %}
      <span class="lbl">Mode:</span><span class="val" style="font-family:inherit;">{{ doc.mode_of_payment }}</span>
    {% endif %}
  </div>
  {% endif %}

  <div class="footer">
    Computer-generated payslip — no signature required. Queries: hr@sungas.org
  </div>

</div>
